// Round 7 (midi): the checks of "Test MIDI export" that need no plugin DLL: `FruityHost midi-test [--only id,id] [--no-mutants]`, and the first half of `selftest --only midi`.
//
//   converter         the copy of VRUN's converter (Plugin/BrokenNes2.Plugin/Music/Vrun) against VRUN's own: the same sources, VRUN's two baked music_data.fab files regenerated byte for byte,
//                     the same output and log as VRUN's own midi2nes CLI on every roster song and on the songs written here, and the plugin's conversion path giving those streams
//   synthetic-port    the synthetic FL-style song written here is byte for byte BrokenDev's make_test_mid.py output
//   template          the bundled template against a fresh build by BrokenDev/tools/music/build-musictest.ps1: the same manifest (but the ROM's hash), every differing byte inside the strings
//                     or a pointer to one (NESFab moves a few strings between builds), and the same sound, picture and player state frame by frame when both carry the same songs
//   template-refusals a template of another format, version, opcode format, region size, ROM, mapper, period table, or whose offsets do not point at what they say, is refused with the reason
//   engine            the ROM the plugin builds (template + patch) plays exactly the converter's streams, frame by frame, loop included (the decoder model), with three negative controls
//                     per song; the decode starts in the frame MusicTemplate.Preroll says; the player's loop counter turns at the song's loop length
//   reference         the same songs built the slow way (a full one-song AudioPlayer build by VRUN's toolchain) play the same register writes, frame for frame, as the patched template
//   facts             the short facts the window shows say what the converter did (thinned, truncated, dropped channels, tempo changes, bends, low notes), and files that cannot be used are refused
//   section           the project section SNG1: round trip, every truncation and flipped bit refused, newer versions and unknown flags refused, lengths that lie refused
//   title             the title and loop length written into the template follow the AudioPlayer's own rules
//   bends             (round 9) pitch bends: songs without a played bend convert byte for byte as without bends; on the ROM, the bend songs' pitch follows the MIDI's (held bends exact,
//                     moving ones within the tolerance), and the volume / triangle / noise registers are those of the same song without bends in every frame (no note moves)
//
// Round 9: the registers are compared as each frame's NMI left them (MidiRun.Latch, Music/NmiLatch.cs): the template's bend decoders make a busy frame's NMI write on past the frame's
// end, where round 7 read the latch; the frames where the two differ are counted in the engine check's notes.
//
// Without the VRUN tree, converter / template / reference (and the roster part of engine) are NOT RUN and said so, never passed. Each check is shown able to fail by a deliberate bug.
using System.Diagnostics;
using System.Text;
using BrokenNes2.Music;
using Vrun.Audio;

namespace BrokenNes.FruityHost;

internal static class MidiChecks
{
    public sealed record Check(string Id, string What, Action<ImodelReport> Run);
    public sealed record CheckOutcome(string Id, string What, bool Passed, double Seconds, ImodelReport Report);

    public static readonly Check[] All =
    [
        new("synthetic-port", "the synthetic FL-style song written here is BrokenDev's make_test_mid.py output, byte for byte", SyntheticPort),
        new("converter", "the plugin's copy of VRUN's converter equals VRUN's own (sources, the baked music_data.fab files, the CLI's output and log on every song), and the plugin's conversion path gives those streams", Converter),
        new("title", "the song's name and loop length are written into the template as the AudioPlayer's roster would have them; the rest of each region is its filler", Title),
        new("template-refusals", "a template the code does not know (format, version, opcodes, region, ROM, mapper, period table, offsets) is refused with the reason", TemplateRefusals),
        new("template", "the bundled template equals a fresh build of the script in what it is and does (manifest, bytes outside the strings, sound, picture and player state with the same songs)", Template),
        new("engine", "the ROM the plugin builds plays the converter's streams frame by frame (decoder model, three negative controls per song), the decode starts after the preroll, the loop counter turns at the loop length", Engine),
        new("reference", "a full rebuild of each song by VRUN's toolchain plays the same register writes and player state, frame for frame, as the template with the song patched in", Reference),
        new("bends", "pitch bends (round 9): a song without a played bend converts byte for byte as without bends; with bends, the ROM's own pitch follows the MIDI's (held bends exact, moving ones within the tolerance) and no note moves", BendsCheck),
        new("facts", "the facts say what the converter did, and the files that cannot be used are refused with the reason", Facts),
        new("section", "the project section SNG1 round-trips and refuses damage, newer versions and unknown flags", Section),
    ];

    // ---- shared ----

    private static MusicTemplate BundledTemplate()
    {
        var (rom, manifest, _) = MidiFixtures.Bundled();
        return MusicTemplate.Load(rom, manifest, out var why) ?? throw new InvalidOperationException("the bundled template does not load: " + why);
    }

    private static void NotRun(ImodelReport r, string what) => r.Warn("NOT RUN: " + what + " (the VRUN tree is not on this machine: BrokenDev\\brokendev.ps1 restore vrun_nes_dev, or set BROKENNES_VRUN)");

    private static string Norm(string s) => s.Replace("\r\n", "\n");

    /// <summary>The template the checks build once per run (the script's template mode), with VRUN's CLI built in its scratch copy as a side effect. Null with the reason.</summary>
    private static (string Dir, string Work)? freshTemplate;
    private static string? freshProblem;
    private static (string Dir, string Work)? FreshTemplate(out string? problem)
    {
        if (freshTemplate != null || freshProblem != null) { problem = freshProblem; return freshTemplate; }
        string outDir = MidiFixtures.Work("template-" + Environment.ProcessId), work = MidiFixtures.Work("scratch");
        var p = MidiFixtures.BuildScript("template", outDir, work);
        if (p.Exit != 0) { freshProblem = $"build-musictest.ps1 failed (exit {p.Exit}): {p.Output.Trim().Split('\n').LastOrDefault()}"; problem = freshProblem; return null; }
        freshTemplate = (outDir, work);
        problem = null;
        return freshTemplate;
    }

    /// <summary>Every song the checks convert: the roster (with the VRUN tree) and the ones written here, the pitch-bend songs included (round 9).</summary>
    private static List<MidiSong> Songs() => [.. MidiFixtures.RosterSongs(), .. MidiFixtures.Stress(), .. MidiFixtures.BendSongs()];

    /// <summary>The songs the plugin plays (the drums-only one is refused by design: the converter would play nothing of it).</summary>
    private static List<MidiSong> Playable() => Songs().Where(s => SongConvert.Convert(s.Midi, out _) != null).ToList();

    private static byte[][] VrunStreams(string fab, string name)
    {
        var streams = new byte[4][];
        for (int c = 0; c < 4; c++)
        {
            var m = System.Text.RegularExpressions.Regex.Match(fab, @"\[\]\s+music_" + name + "_" + Midi2Nes.ChannelNames[c] + @"\s*\n\s*U\[(\d+)\]\(([^)]*)\)");
            if (!m.Success) throw new InvalidDataException($"no {Midi2Nes.ChannelNames[c]} stream for {name}");
            streams[c] = m.Groups[2].Value.Split(',').Select(v => byte.Parse(v.Trim())).ToArray();
        }
        return streams;
    }

    // =====================================================================================================================================================================

    public static void SyntheticPort(ImodelReport r)
    {
        string? py = null;
        foreach (var cand in new[] { "python", "py" })
        {
            try { var t = MidiFixtures.Run(cand, ["-I", "-c", "import sys; print(sys.version_info[0])"], timeoutSec: 60); if (t.Exit == 0 && t.Output.Trim().StartsWith('3')) { py = cand; break; } }
            catch (System.ComponentModel.Win32Exception) { }
        }
        if (py == null) { r.Warn("NOT RUN: no Python 3 on this machine, so the port of make_test_mid.py is not compared with the original"); return; }
        string outFile = Path.Combine(MidiFixtures.Work("synthetic"), "song.mid");
        var p = MidiFixtures.Run(py, ["-I", Path.Combine(MidiFixtures.RepoRoot(), @"BrokenDev\tools\music\make_test_mid.py"), outFile], timeoutSec: 60);
        r.Expect(p.Exit == 0 && File.Exists(outFile), "make_test_mid.py did not run: " + p.Output);
        if (!File.Exists(outFile)) return;
        var original = File.ReadAllBytes(outFile);
        var port = MidiFixtures.Synthetic();
        r.Expect(original.AsSpan().SequenceEqual(port), $"the C# synthetic song ({port.Length} bytes) differs from make_test_mid.py's ({original.Length} bytes)");
        r.Note($"the synthetic song: {port.Length} bytes, the same as make_test_mid.py's");
    }

    public static void Converter(ImodelReport r)
    {
        var vrun = MidiFixtures.Vrun();
        if (vrun == null) { NotRun(r, "the converter identity check"); return; }
        // 1. the sources (line endings aside: git checks the copies out with CRLF)
        string ours = Path.Combine(MidiFixtures.RepoRoot(), @"Plugin\BrokenNes2.Plugin\Music\Vrun");
        foreach (var f in new[] { "MidiFile.cs", "Midi2Nes.cs", "FabWriter.cs", "Bends.cs" })
            r.Expect(Norm(File.ReadAllText(Path.Combine(ours, f))) == Norm(File.ReadAllText(Path.Combine(vrun, @"engine\audio\converter", f))), $"{f}: the copy in BrokenNes is not VRUN's current source (copy it again, then rerun these checks)");

        // 2. VRUN's baked music_data.fab files, regenerated byte for byte (the converter's own job in VRUN's build: build_music.py runs it per roster track, the first writes the period tables)
        int regenerated = 0;
        foreach (var (rosterRel, fabRel, reportRel) in new[] { (@"src\audioplayer\roster.json", @"src\audioplayer\music_data.fab", @"src\audioplayer\build_report.json"), (@"src\game\music_roster.json", @"src\game\music_data.fab", (string?)null) })
        {
            string roster = Path.Combine(vrun, rosterRel), baked = Path.Combine(vrun, fabRel);
            if (!File.Exists(roster) || !File.Exists(baked)) { r.Warn($"NOT RUN: {rosterRel} or {fabRel} is missing"); continue; }
            var sb = new StringBuilder();
            var tracks = MidiFixtures.Roster(roster);
            var logs = new List<List<string>>();
            for (int i = 0; i < tracks.Count; i++)
            {
                var log = new List<string>();
                var result = Midi2Nes.ConvertSong(MidiFile.Parse(File.ReadAllBytes(tracks[i].Path)), tracks[i].Name, log.Add);
                sb.Append(FabWriter.SongText(result, i == 0, tracks[i].Midi));
                logs.Add(log);
            }
            string mine = sb.ToString(), theirs = File.ReadAllText(baked);
            bool same = mine == theirs;
            r.Expect(same, $"{fabRel}: regenerated by the BrokenNes copy it differs from VRUN's ({mine.Length} vs {theirs.Length} characters, first difference at {FirstDiff(mine, theirs)})");
            if (same) regenerated++;
            if (reportRel != null && File.Exists(Path.Combine(vrun, reportRel)))
            {
                using var doc = System.Text.Json.JsonDocument.Parse(File.ReadAllText(Path.Combine(vrun, reportRel)));
                int t = 0;
                foreach (var tr in doc.RootElement.GetProperty("tracks").EnumerateArray())
                {
                    var theirLog = tr.GetProperty("log").EnumerateArray().Select(e => e.GetString() ?? "").ToList();
                    r.Expect(t < logs.Count && theirLog.Take(logs[t].Count).SequenceEqual(logs[t]), $"{reportRel}: track {t}'s converter log differs from the copy's");
                    t++;
                }
            }
        }
        r.Note($"{regenerated} of VRUN's baked music_data.fab files regenerated byte for byte by the copy");

        // 3. VRUN's own CLI on every song (its scratch build: the template script builds it through build_music.py)
        var fresh = FreshTemplate(out var why);
        if (fresh == null) { r.Expect(false, "the template script did not run, so VRUN's CLI was not built: " + why); return; }
        var cli = MidiFixtures.VrunCli(fresh.Value.Work);
        if (cli == null) { r.Expect(false, "VRUN's converter CLI was not found in the scratch copy"); return; }
        string dir = MidiFixtures.Work("cli");
        int compared = 0, refusedBoth = 0, bendSongs = 0;
        foreach (var s in Songs().Concat(MidiFixtures.Refused()))
        {
            string mid = Path.Combine(dir, s.Name + ".mid"), fab = Path.Combine(dir, s.Name + ".fab");
            File.WriteAllBytes(mid, s.Midi);
            if (File.Exists(fab)) File.Delete(fab);
            var p = MidiFixtures.Run("dotnet", [cli, mid, "--out", fab, "--name", s.Name], timeoutSec: 120);
            SongResult? result = null;
            var log = new List<string>();
            try { result = Midi2Nes.ConvertSong(MidiFile.Parse(s.Midi), s.Name, log.Add); }
            catch (Exception e) when (e is FormatException or IndexOutOfRangeException or ArgumentOutOfRangeException) { }
            if (p.Exit != 0 || result == null)
            {
                r.Expect(p.Exit != 0 && result == null, $"{s.Name}: VRUN's CLI {(p.Exit == 0 ? "converted" : "refused")} it, the copy {(result != null ? "converted" : "refused")} it");
                refusedBoth++;
                continue;
            }
            string theirs = File.ReadAllText(fab);
            string mine = FabWriter.SongText(result, true, mid);
            r.Expect(mine == theirs, $"{s.Name}: the copy's music_data.fab differs from VRUN's CLI's (first difference at {FirstDiff(mine, theirs)})");
            // the CLI prints the converter's log, then its own summary
            int total = result.UntruncatedLengths.Sum();
            var expected = log.Concat([$"[midi2nes] {mid} -> {fab} ({s.Name}): {total} bytes across 4 channels"]).Concat(Enumerable.Range(0, 4).Select(c => $"  {Midi2Nes.ChannelNames[c]}: {result.UntruncatedLengths[c]} bytes")).ToList();
            var printed = p.Output.Replace("\r", "").Split('\n').Where(l => l.Length > 0).ToList();
            r.Expect(printed.SequenceEqual(expected), $"{s.Name}: VRUN's CLI printed other log lines than the copy's converter ({printed.Count} vs {expected.Count})");
            // round 9: the same with --bends (what the plugin converts with): VRUN's CLI and the copy agree, and a song with no bend played is byte for byte the song without --bends
            string fabB = Path.Combine(dir, s.Name + ".bends.fab");
            if (File.Exists(fabB)) File.Delete(fabB);
            var pb = MidiFixtures.Run("dotnet", [cli, mid, "--out", fabB, "--name", s.Name, "--bends"], timeoutSec: 120);
            var logB = new List<string>();
            var resultB = Midi2Nes.ConvertSong(MidiFile.Parse(s.Midi), s.Name, logB.Add, new ConvertOptions { Bends = true });
            string theirsB = pb.Exit == 0 && File.Exists(fabB) ? File.ReadAllText(fabB) : "";
            r.Expect(pb.Exit == 0 && FabWriter.SongText(resultB, true, mid) == theirsB, $"{s.Name}: with --bends the copy's music_data.fab differs from VRUN's CLI's (exit {pb.Exit}, first difference at {FirstDiff(FabWriter.SongText(resultB, true, mid), theirsB)})");
            var expectedB = logB.Concat([$"[midi2nes] {mid} -> {fabB} ({s.Name}): {resultB.UntruncatedLengths.Sum()} bytes across 4 channels"]).Concat(Enumerable.Range(0, 4).Select(c => $"  {Midi2Nes.ChannelNames[c]}: {resultB.UntruncatedLengths[c]} bytes")).ToList();
            r.Expect(pb.Output.Replace("\r", "").Split('\n').Where(l => l.Length > 0).SequenceEqual(expectedB), $"{s.Name}: with --bends VRUN's CLI printed other log lines than the copy's converter");
            bool bendsPlayed = resultB.Bends.Any(x => !x.Ignored && !x.Dropped);
            if (!bendsPlayed) r.Expect(VrunStreams(theirsB, s.Name).Zip(VrunStreams(theirs, s.Name)).All(z => z.First.AsSpan().SequenceEqual(z.Second)), $"{s.Name}: no channel plays a bend, yet VRUN's streams with --bends differ from those without");
            else bendSongs++;
            // the plugin's own path (SongConvert, what the plugin patches into the template: bends on) gives VRUN's --bends streams; a song it refuses by design (no notes, drums only: nothing would play) is said so
            var build = SongConvert.Convert(s.Midi, out var problem);
            var vrunStreams = VrunStreams(theirsB, s.Name);
            if (build == null && problem != null && (problem.Contains("no notes") || problem.Contains("nothing would play")))
                r.Expect(!vrunStreams.Any(HasNote), $"{s.Name}: the plugin refuses it as silent ('{problem}') but VRUN's streams hold notes");
            else r.Expect(build != null && Enumerable.Range(0, 4).All(c => build.Channels[c].AsSpan().SequenceEqual(vrunStreams[c])), $"{s.Name}: the plugin's conversion path does not give VRUN's streams (with --bends)" + (problem != null ? ": " + problem : ""));
            compared++;
        }
        r.Note($"VRUN's CLI and the copy agree on {compared} songs (output file and log, without and with --bends; the plugin's streams) and both refuse {refusedBoth} files; {bendSongs} of them play bends, the others are byte for byte the same with --bends");
        r.Expect(compared >= 11 + 5, $"only {compared} songs were compared");
    }

    /// <summary>Whether a stream holds a note-on (an opcode below $80; the byte after $D0 is a wait length, not an opcode).</summary>
    private static bool HasNote(byte[] s)
    {
        for (int i = 0; i < s.Length; i++)
        {
            if (s[i] < 0x80) return true;
            if (s[i] == 0xD0) i++;
            else if (s[i] == 0xFF) return false;
        }
        return false;
    }

    private static int FirstDiff(string a, string b)
    {
        int n = Math.Min(a.Length, b.Length);
        for (int i = 0; i < n; i++) if (a[i] != b[i]) return i;
        return a.Length == b.Length ? -1 : n;
    }

    public static void Title(ImodelReport r)
    {
        foreach (var (name, want) in new[] { ("My Song", "MY SONG"), ("level 2 (final)", "LEVEL 2 (FINAL)"), ("  lots   of   spaces  ", "LOTS OF SPACES"), ("ünïcödé_and*stars", "NCDANDSTARS"), ("", "MIDI TEST"), ("***", "MIDI TEST"),
                     ("a very long title that goes past twenty-four", "A VERY LONG TITLE THAT G") })
            r.Expect(MusicTemplate.Title(name) == want, $"the title of '{name}' is '{MusicTemplate.Title(name)}', expected '{want}'");
        var t = BundledTemplate();
        var build = SongConvert.Convert(MidiFixtures.Synthetic(), out _)!;
        var rom = t.Patch(build.Channels, build.Facts.LoopFrames, "My Song");
        var title = rom.AsSpan(MusicTemplate.HeaderBytes + t.TitleOffset, t.TitleBytes);
        r.Expect(title[0] == 'M' - 32 && title[6] == 'G' - 32 && title[7] == MusicTemplate.StringEnd && title[^1] == MusicTemplate.StringEnd, "the title is not written as the AudioPlayer's charmap has it (ASCII - 32, then the end mark)");
        foreach (int o in t.LoopLo) r.Expect(rom[MusicTemplate.HeaderBytes + o] == (build.Facts.LoopFrames & 0xFF), "a low byte of the loop length is not the song's");
        foreach (int o in t.LoopHi) r.Expect(rom[MusicTemplate.HeaderBytes + o] == build.Facts.LoopFrames >> 8, "a high byte of the loop length is not the song's");
        for (int c = 0; c < 4; c++)
        {
            var region = rom.AsSpan(MusicTemplate.HeaderBytes + t.Offsets[c], t.Region);
            r.Expect(region[..build.Channels[c].Length].SequenceEqual(build.Channels[c]), $"{MusicTemplate.ChannelNames[c]}: the stream is not at the region's start");
            int fill = 0;
            for (int i = build.Channels[c].Length; i < region.Length; i++) if (region[i] == t.Fillers[c]) fill++;
            r.Expect(fill == region.Length - build.Channels[c].Length, $"{MusicTemplate.ChannelNames[c]}: {region.Length - build.Channels[c].Length - fill} bytes after the stream are not the filler (something of the template's own song is left)");
        }
        // nothing outside the regions, the title and the loop bytes changed
        var touched = new HashSet<int>();
        for (int c = 0; c < 4; c++) for (int i = 0; i < t.Region; i++) touched.Add(MusicTemplate.HeaderBytes + t.Offsets[c] + i);
        for (int i = 0; i < t.TitleBytes; i++) touched.Add(MusicTemplate.HeaderBytes + t.TitleOffset + i);
        foreach (int o in t.LoopLo.Concat(t.LoopHi)) touched.Add(MusicTemplate.HeaderBytes + o);
        int outside = 0;
        for (int i = 0; i < rom.Length; i++) if (rom[i] != t.Rom[i] && !touched.Contains(i)) outside++;
        r.Expect(outside == 0, $"{outside} bytes changed outside the regions, the title and the loop length");
    }

    public static void TemplateRefusals(ImodelReport r)
    {
        var (rom, manifest, _) = MidiFixtures.Bundled();
        r.Expect(MusicTemplate.Load(rom, manifest, out var ok) != null, "the bundled template is refused: " + ok);
        string Edit(string key, string value) => string.Join("\n", Norm(manifest).Split('\n').Select(l => l.StartsWith(key + " =") ? key + " = " + value : l));
        var man = MusicTemplate.ParseManifest(manifest)!;
        int Off(string key) => Convert.ToInt32(man[key][2..], 16);
        string Hex6(int v) => $"0x{v:X6}";
        var cases = new List<(string What, byte[] Rom, string Manifest)>
        {
            ("version 3", rom, Edit("version", "3")),
            ("version 1 (round 7's: plain decoders, a bend opcode would read as the loop)", rom, Edit("version", "1")),
            ("another format", rom, Edit("format", "something-else")),
            ("another opcode format", rom, Edit("opcodes", "vrun-music-3")),
            ("round 7's opcode format", rom, Edit("opcodes", "vrun-music-1")),
            ("no bend decoder on the triangle", rom, Edit("bend-decoders", "square1 square2")),
            ("no bend decoders named", rom, string.Join("\n", Norm(manifest).Split('\n').Where(l => !l.StartsWith("bend-decoders")))),
            ("another region size", rom, Edit("region", "1024")),
            ("square 1 one byte off", rom, Edit("square1", Hex6(Off("square1") + 1))),
            ("noise at square 2's place", rom, Edit("noise", man["square2"])),
            ("a region outside the ROM", rom, Edit("triangle", "0x07FFF0")),
            ("the title elsewhere", rom, Edit("title", Hex6(Off("title") + 1))),
            ("a loop byte elsewhere", rom, Edit("loop-lo", string.Join(" ", man["loop-lo"].Split(' ').Select((o, i) => i == 0 ? Hex6(Convert.ToInt32(o[2..], 16) + 1) : o)))),
            ("another period table", rom, Edit("periods-sha256", new string('0', 64))),
            ("no version", rom, Edit("version", "x")),
            ("not a manifest", rom, "this is not a manifest"),
            ("an empty manifest", rom, ""),
        };
        var other = (byte[])rom.Clone(); other[0x100] ^= 1;
        cases.Add(("a ROM changed by one bit", other, manifest));
        var notInes = (byte[])rom.Clone(); notInes[0] = (byte)'X';
        cases.Add(("not an iNES file (with its hash)", notInes, Edit("rom-sha256", MusicTemplate.Sha256Hex(notInes))));
        var mapper = (byte[])rom.Clone(); mapper[6] = (byte)(mapper[6] & 0x0F | 0x10);
        cases.Add(("mapper 1 (with its hash)", mapper, Edit("rom-sha256", MusicTemplate.Sha256Hex(mapper))));
        cases.Add(("a shorter ROM", rom[..^16], manifest));
        foreach (var (what, crom, cman) in cases)
        {
            var t = MusicTemplate.Load(crom, cman, out var why);
            r.Expect(t == null && !string.IsNullOrEmpty(why), $"{what}: the template was accepted");
        }
        // round 7's own template (version 1, bundled until round 9) is refused with the reason, whatever else it says
        var round7 = string.Join("\n", Norm(manifest).Split('\n').Select(l => l.StartsWith("version =") ? "version = 1" : l.StartsWith("opcodes =") ? "opcodes = vrun-music-1" : l).Where(l => !l.StartsWith("bend-decoders")));
        r.Expect(MusicTemplate.Load(rom, round7, out var w7) == null && w7 != null && w7.Contains("version 1") && w7.Contains("pitch bends"), "round 7's template (version 1) was not refused with its reason: " + w7);
        r.Note($"{cases.Count + 1} broken or old templates refused, each with its reason (for example: '{w7}')");
    }

    // ---- the template against a fresh build ----

    /// <summary>The msg_* labels of a .mlb: PRG offset ranges of the strings.</summary>
    private static List<(string Name, int Start, int End)> Strings(string mlb)
    {
        var list = new List<(string, int, int)>();
        foreach (var line in Norm(mlb).Split('\n'))
        {
            var m = System.Text.RegularExpressions.Regex.Match(line, @"^NesPrgRom:([0-9A-Fa-f]+)-([0-9A-Fa-f]+):(msg_\w+?)@");
            if (m.Success) list.Add((m.Groups[3].Value, Convert.ToInt32(m.Groups[1].Value, 16), Convert.ToInt32(m.Groups[2].Value, 16)));
        }
        return list;
    }

    /// <summary>Bytes that differ between two builds and are neither inside a string in both nor a pointer to the SAME string in both (its address's low or high byte in A, the same byte of
    /// the same string's address in B: a pointer that followed a string that moved).</summary>
    internal static List<string> UnexplainedDiffs(byte[] a, string mlbA, byte[] b, string mlbB)
    {
        var sa = Strings(mlbA); var sb = Strings(mlbB).ToDictionary(x => x.Name);
        var bad = new List<string>();
        if (a.Length != b.Length) { bad.Add($"sizes {a.Length} and {b.Length}"); return bad; }
        bool InString(IEnumerable<(string, int Start, int End)> s, int off) => s.Any(x => off >= x.Start && off <= x.End);
        // a string's CPU address in a 16 KB bank window: $8000 (or $C000) + its offset within the bank
        static int Lo(int start) => start & 0xFF;
        static int Hi(int start, int window) => (window | start & 0x3FFF) >> 8;
        bool SamePointer(byte va, byte vb) => sa.Any(x => sb.TryGetValue(x.Name, out var y) && x.Start != y.Start
            && (Lo(x.Start) == va && Lo(y.Start) == vb || Hi(x.Start, 0x8000) == va && Hi(y.Start, 0x8000) == vb || Hi(x.Start, 0xC000) == va && Hi(y.Start, 0xC000) == vb));
        for (int i = MusicTemplate.HeaderBytes; i < a.Length; i++)
        {
            if (a[i] == b[i]) continue;
            int off = i - MusicTemplate.HeaderBytes;
            if (InString(sa, off) && InString(sb.Values, off)) continue;
            if (SamePointer(a[i], b[i])) continue;
            if (bad.Count < 8) bad.Add($"PRG 0x{off:X6}: 0x{a[i]:X2} / 0x{b[i]:X2}");
            else { bad.Add("..."); break; }
        }
        return bad;
    }

    /// <summary>Test-side deliberate bug of the template check: the fresh build is changed in one byte of the engine's code (the first byte of the square 1 decoder's bank that is not a string).</summary>
    internal static bool FreshEngineByteFlipped;

    public static void Template(ImodelReport r)
    {
        if (MidiFixtures.Vrun() == null) { NotRun(r, "the template equality check"); return; }
        var fresh = FreshTemplate(out var why);
        if (fresh == null) { r.Expect(false, why ?? "the template script failed"); return; }
        var (rom, manifest, mlb) = MidiFixtures.Bundled();
        var fRom = File.ReadAllBytes(Path.Combine(fresh.Value.Dir, "musictest.nes"));
        var fMan = File.ReadAllText(Path.Combine(fresh.Value.Dir, "musictest.txt"));
        var fMlb = File.ReadAllText(Path.Combine(fresh.Value.Dir, "musictest.mlb"));
        if (FreshEngineByteFlipped) fRom[MusicTemplate.HeaderBytes + 0x014000] ^= 0x20;       // start_music_track's first byte (the .mlb names it at PRG 0x014000)
        // the manifests: everything but the ROM's hash
        string Strip(string m) => string.Join("\n", Norm(m).Split('\n').Where(l => !l.StartsWith("rom-sha256")));
        r.Expect(Strip(manifest) == Strip(fMan), "the fresh build's manifest differs from the bundled one (offsets, title, loop bytes, period table or VRUN sources)");
        // the bytes: only the strings and the pointers to them may differ
        var unexplained = UnexplainedDiffs(rom, mlb, fRom, fMlb);
        int differing = 0;
        for (int i = 0; i < rom.Length && i < fRom.Length; i++) if (rom[i] != fRom[i]) differing++;
        r.Expect(unexplained.Count == 0, "bytes differ outside the strings and their pointers: " + string.Join(", ", unexplained));
        // what it does: the same songs patched into both, frame by frame
        var mine = MusicTemplate.Load(rom, manifest, out var w1);
        string fManNow = FreshEngineByteFlipped ? System.Text.RegularExpressions.Regex.Replace(fMan, @"rom-sha256 = \w+", "rom-sha256 = " + MusicTemplate.Sha256Hex(fRom)) : fMan;
        var theirs = MusicTemplate.Load(fRom, fManNow, out var w2);
        r.Expect(mine != null && theirs != null, $"a template does not load: {w1} {w2}");
        if (mine == null || theirs == null) return;
        int songs = 0, frames = 0;
        foreach (var s in Songs().Where(x => x.Name is "synthetic" or "dense" or "long" or "think" or "level2" or "vectorplane" or "bendall" or "benddense"))
        {
            var b = SongConvert.Convert(s.Midi, out _);
            if (b == null) continue;
            const int n = 420;
            var ra = MidiRun.Of(mine.Patch(b.Channels, b.Facts.LoopFrames, s.Name), n, mlb);
            var rb = MidiRun.Of(theirs.Patch(b.Channels, b.Facts.LoopFrames, s.Name), n, fMlb);
            r.Expect(ra.Latch.AsSpan().SequenceEqual(rb.Latch), $"{s.Name}: the two templates write other sound registers");
            r.Expect(ra.Picture.SequenceEqual(rb.Picture), $"{s.Name}: the two templates draw other pictures (first at frame {FirstDiff(ra.Picture, rb.Picture)})");
            r.Expect(ra.Loops.SequenceEqual(rb.Loops) && ra.Position.SequenceEqual(rb.Position), $"{s.Name}: the two templates' players count other positions or loops");
            songs++; frames += n;
        }
        r.Note($"bundled template vs a fresh build: {differing} bytes differ, all inside the strings or pointers to them; {songs} songs x 420 frames: the same sound registers, pictures and player state");
    }

    private static int FirstDiff(long[] a, long[] b) { for (int i = 0; i < Math.Min(a.Length, b.Length); i++) if (a[i] != b[i]) return i; return -1; }

    // ---- the engine ----

    public sealed record EngineResult(string Song, MidiModel.Score Score, bool ControlsFailed, int LoopTurn, int LoopFrames)
    {
        /// <summary>Frames whose NMI wrote on past the frame's end (round 9; compared through the per-NMI latch, so they agree; counted).</summary>
        public int LateFrames { get; init; }
    }

    /// <summary>The first frame of the decode is not compared with the model (decoder_model.py's SKIP; measured here on the latch: in the frame the player starts the track, the noise
    /// registers still hold the silence its start wrote (pl_silence: $400C = $30) and the noise's first note shows in the next frame, while the model has it at once; from the second
    /// frame on every field agrees). That frame IS compared byte for byte with the full rebuild (check "reference"): there the template behaves exactly as VRUN's own build does.</summary>
    internal const int Skip = 1;

    /// <summary>One song through the plugin's path (convert, patch the bundled template) on the plugin's machine, scored against the model, with the three negative controls.</summary>
    internal static EngineResult EngineOne(ImodelReport r, MidiSong s, MusicTemplate t, string mlb, MidiSong other)
    {
        var b = SongConvert.Convert(s.Midi, out var why) ?? throw new InvalidOperationException($"{s.Name}: {why}");
        int loop = b.Facts.LoopFrames;
        int n = Math.Clamp(loop + 120, 560, 2400);
        var run = MidiRun.Of(t.Patch(b.Channels, loop, s.Name), n + 120, mlb);
        var sc = MidiModel.Best(b.Channels, run.Latch, n, skip: Skip);
        // negative controls (decoder_model.py's): the model's first 8 square-1 notes a semitone off, the decode start one frame late, another song's streams
        var corrupt = b.Channels.Select(c => (byte[])c.Clone()).ToArray();
        int left = 8;
        for (int i = 0; i < corrupt[0].Length && left > 0; i++)
        {
            byte op = corrupt[0][i];
            if (op < 0x80) { corrupt[0][i] ^= 1; left--; } else if (op == 0xD0) i++; else if (op == 0xFF) break;
        }
        bool c1 = left == 8 || MidiModel.ScoreAt(corrupt, run.Latch, sc.Start, n, Skip).Worst < 1;    // (a song with no square-1 note has nothing to corrupt there)
        bool c2 = MidiModel.ScoreAt(b.Channels, run.Latch, sc.Start + 1, n, Skip).Worst < 1;
        var ob = SongConvert.Convert(other.Midi, out _)!;
        bool c3 = MidiModel.Best(ob.Channels, run.Latch, n, skip: Skip).Worst < 1;
        // round 9: on a song that slides, the model with every slide negated must not match either
        bool c4 = !b.Channels.Take(3).Any(HasSlide) || MidiModel.ScoreAt(b.Channels, run.Latch, sc.Start, n, Skip, flipSlides: true).Worst < 1;
        // the player's loop counter (RAM pl_loops) turns once per loop length
        int turn = Array.FindIndex(run.Loops, v => v > 0);
        return new EngineResult(s.Name, sc, c1 && c2 && c3 && c4, turn < 0 ? -1 : turn - sc.Start, loop) { LateFrames = run.LateFrames };
    }

    /// <summary>Whether a stream holds a slide opcode ($D2; operands skipped).</summary>
    internal static bool HasSlide(byte[] s)
    {
        for (int i = 0; i < s.Length; i++)
        {
            byte op = s[i];
            if (op == Vrun.Audio.Bends.OpSlide) return true;
            if (op == 0xD0) i++;
            else if (op == Vrun.Audio.Bends.OpPitch) i += 2;
            else if (op == 0xFF) return false;
        }
        return false;
    }

    public static void Engine(ImodelReport r)
    {
        var t = BundledTemplate();
        var (_, _, mlb) = MidiFixtures.Bundled();
        var songs = Playable();
        if (MidiFixtures.Vrun() == null) NotRun(r, "the engine check on VRUN's eleven roster songs (the songs written here were checked)");
        int exact = 0, late = 0;
        var starts = new List<int>();
        for (int i = 0; i < songs.Count; i++)
        {
            var s = songs[i];
            var res = EngineOne(r, s, t, mlb, songs[(i + 1) % songs.Count]);
            r.Expect(res.Score.Worst >= 1.0, $"{s.Name}: the patched ROM does not play the converter's streams: {res.Score.Agree}/{res.Score.Of} field-frames agree; {string.Join("; ", res.Score.Mismatches)}");
            r.Expect(res.ControlsFailed, $"{s.Name}: a negative control did not fail (the check cannot be trusted on this song)");
            r.Expect(res.Score.Start == MusicTemplate.Preroll, $"{s.Name}: the decode starts in frame {res.Score.Start} (0-based), the plugin's preroll assumes {MusicTemplate.Preroll}");
            if (res.LoopFrames + 4 < 2400) r.Expect(res.LoopTurn >= res.LoopFrames - 3 && res.LoopTurn <= res.LoopFrames + 3, $"{s.Name}: the player's loop counter turned {res.LoopTurn} frames after the decode began, the song's loop is {res.LoopFrames}");
            if (res.Score.Worst >= 1.0) exact++;
            starts.Add(res.Score.Start);
            r.Note($"{s.Name,-14} {res.Score.Agree,6}/{res.Score.Of} field-frames, decode from frame {res.Score.Start}, loop {res.LoopFrames}" + (res.LoopTurn >= 0 ? $", loop counter turned at +{res.LoopTurn}" : "")
                + (res.LateFrames > 0 ? $"; {res.LateFrames} frames whose NMI wrote on past the frame's end" : ""));
            late += res.LateFrames;
        }
        r.Note($"{late} frames in all where the NMI was still writing when the frame ended (compared as the NMI left them: Music/NmiLatch.cs)");
        r.Note($"{exact} of {songs.Count} songs played exactly as the converter's streams say; the decode began in frame {string.Join("/", starts.Distinct())}");
    }

    // ---- the slow way: a full rebuild per song ----

    public static void Reference(ImodelReport r)
    {
        if (MidiFixtures.Vrun() == null) { NotRun(r, "the full-rebuild reference"); return; }
        var t = BundledTemplate();
        var (_, _, mlb) = MidiFixtures.Bundled();
        string cache = MidiFixtures.Work("reference");
        int same = 0, songs = 0, lagged = 0;
        foreach (var s in Playable().Where(x => x.Name is not ("manychannels" or "lownotes")))
        {
            var b = SongConvert.Convert(s.Midi, out _)!;
            // (the opcode format in the key: a rebuild cached by round 7's toolchain is not the reference of round 9's, whose build plays bends)
            string key = MusicTemplate.Sha256Hex([.. s.Midi, .. System.Text.Encoding.ASCII.GetBytes(MusicTemplate.Opcodes)])[..16];
            string dir = Path.Combine(cache, $"{s.Name}-{key}");
            string romFile = Path.Combine(dir, "song.nes"), mlbFile = Path.Combine(dir, "song.mlb");
            if (!File.Exists(romFile))
            {
                string mid = Path.Combine(cache, s.Name + ".mid");
                File.WriteAllBytes(mid, s.Midi);
                var p = MidiFixtures.BuildScript("song", dir, MidiFixtures.Work("scratch"), mid, "song");
                if (p.Exit != 0) { r.Expect(false, $"{s.Name}: the full rebuild failed: {p.Output.Trim().Split('\n').LastOrDefault()}"); continue; }
            }
            int n = Math.Clamp(b.Facts.LoopFrames + 120, 560, 2400);
            var full = MidiRun.Of(File.ReadAllBytes(romFile), n + 120, File.ReadAllText(mlbFile));
            var patched = MidiRun.Of(t.Patch(b.Channels, b.Facts.LoopFrames, "song"), n + 120, mlb);
            int fs = MidiModel.Best(b.Channels, full.Latch, n, skip: Skip).Start, ps = MidiModel.Best(b.Channels, patched.Latch, n, skip: Skip).Start;
            // the sound registers as each NMI left them: exactly the same. The player's position and loop count are read from RAM when the frame ends, and the NMI that updates them
            // (pl_audio_post, after the decoders) can still be running then, longer in the template (its bend decoders on all three tonal channels) than in a rebuild whose song has
            // fewer bends: a sample may show the previous frame's value. So at every frame the two samples must be equal, or one exactly one player step behind the other (counted);
            // anything else (another loop length, a frame skipped or counted twice) fails.
            int bad = 0, first = -1, ramBad = 0, ramLag = 0, loopLen = b.Facts.LoopFrames;
            string? ramFirst = null;
            for (int k = 0; k < n; k++)
            {
                bool latchEq = full.Latch.AsSpan((fs + k) * MidiModel.LatchBytes, MidiModel.LatchBytes).SequenceEqual(patched.Latch.AsSpan((ps + k) * MidiModel.LatchBytes, MidiModel.LatchBytes));
                if (!latchEq) { bad++; if (first < 0) first = k; }
                var fa = (P: full.Position[fs + k], L: full.Loops[fs + k]);
                var pa = (P: patched.Position[ps + k], L: patched.Loops[ps + k]);
                if (fa == pa) continue;
                // one NMI of the player: the position one step on, back to 0 and one more loop at the song's loop length (the loop count stops at 98: player_ui.fab pl_audio_post)
                (int P, int L) Step((int P, int L) x) => x.P + 1 >= loopLen ? (0, Math.Min(x.L + 1, 98)) : (x.P + 1, x.L);
                if (Step(fa) == pa || Step(pa) == fa) ramLag++;
                else
                {
                    ramBad++;
                    if (ramFirst == null)
                    {
                        string Seq(MidiRun a, int sa) => string.Join(" ", Enumerable.Range(Math.Max(0, k - 2), Math.Min(5, n - Math.Max(0, k - 2))).Select(j => $"{a.Position[sa + j]}/{a.Loops[sa + j]}"));
                        ramFirst = $"+{k}: position/loops around it, rebuild {Seq(full, fs)}; template {Seq(patched, ps)}";
                    }
                }
            }
            r.Expect(bad == 0, $"{s.Name}: the full rebuild and the patched template write other sound registers in {bad} of {n} frames (first at +{first} from the decode start; starts {fs} and {ps})");
            r.Expect(ramBad == 0, $"{s.Name}: the full rebuild and the patched template keep another player position or loop count in {ramBad} of {n} frames (beyond a one-frame lag of the sample; first {ramFirst})");
            r.Expect(fs == ps, $"{s.Name}: the full rebuild decodes from frame {fs}, the patched template from {ps}");
            songs++;
            lagged += ramLag;
            if (bad == 0 && ramBad == 0) same++;
        }
        r.Note($"{same} of {songs} songs: the full rebuild by VRUN's toolchain and the template with the song patched in write the same 24 sound registers as each NMI leaves them, and keep the same player position and loop count, frame for frame ({lagged} frames in all where one ROM's position was read a frame late: its NMI was still running when the frame ended)");
    }

    // ---- pitch bends (round 9) ----

    /// <summary>The MIDI's own pitch on one channel, frame by frame over one loop: the note sounding (-1 none), the bend in semitones (RPN 0 range, 2 by default), and the frames where a
    /// note starts or stops. Written here from the MIDI file, apart from the converter's own reading (Bends.BuildSource), with the same rule: an event belongs to frame
    /// floor(tick x frames-per-tick).</summary>
    internal static (int[] Note, double[] Semis, HashSet<int> NoteFrames) IdealPitch(byte[] midi, int channel, int frames)
    {
        var file = MidiFile.Parse(midi);
        double fpt = ((double)Midi2Nes.FindTempo(file) / file.TicksPerQuarter * Midi2Nes.Fps) / 1_000_000.0;
        var evs = new List<(int Tick, int Order, MidiEvent Ev)>();
        int order = 0;
        foreach (var track in file.Tracks)
        {
            int t = 0;
            foreach (var ev in track) { t += ev.DeltaTime; if (ev.Status < 0xF0 && ev.Channel == channel) evs.Add((t, order++, ev)); }
        }
        evs.Sort((a, b) => a.Tick != b.Tick ? a.Tick.CompareTo(b.Tick) : a.Order.CompareTo(b.Order));
        var note = new int[frames]; var semis = new double[frames]; var changes = new HashSet<int>();
        int cur = -1, bend = 0, msb = 127, lsb = 127, rs = 2, rc = 0, e = 0;
        for (int k = 0; k < frames; k++)
        {
            while (e < evs.Count && (int)(evs[e].Tick * fpt) <= k)
            {
                var ev = evs[e++].Ev;
                if (ev.Command == MidiFile.NoteOn && ev.Data2 > 0) { cur = ev.Data1; changes.Add(k); }
                else if (ev.Command == MidiFile.NoteOff || ev.Command == MidiFile.NoteOn) { cur = -1; changes.Add(k); }
                else if (ev.Command == MidiFile.PitchBend) bend = (ev.Data2 << 7 | ev.Data1) - 8192;
                else if (ev.Command == MidiFile.ControlChange)
                {
                    if (ev.Data1 == 101) msb = ev.Data2; else if (ev.Data1 == 100) lsb = ev.Data2;
                    else if (ev.Data1 == 6 && msb == 0 && lsb == 0) rs = ev.Data2; else if (ev.Data1 == 38 && msb == 0 && lsb == 0) rc = ev.Data2;
                }
            }
            note[k] = cur;
            semis[k] = bend / 8192.0 * (rs + rc / 100.0);
        }
        return (note, semis, changes);
    }

    internal sealed record BendJudgement(int Checked, int Off, int Bent, int Held, double MaxMovingCents, double MaxHeldCents);

    /// <summary>The promise of VRUN's bends, checked on registers the ROM wrote (24 bytes a frame from <paramref name="start"/>, two loops): on the frames that play the MIDI's note (2 frames
    /// either side of a note start or stop belong to the note timing), a bend that holds still (no change 3 frames either side) is exactly on floor(exact period), the period the note table's
    /// rule gives that pitch; a moving one is within the tolerance (or half the bend's speed per frame, when that is more) of the exact pitch, or on one of the two periods around it.
    /// Periods past 0x7FF are not judged. Returns the frames judged and those off.</summary>
    internal static BendJudgement JudgeBends(byte[] latch, int start, int channel, (int[] Note, double[] Semis, HashSet<int> NoteFrames) ideal, int loop, double tol, bool slidesOff)
    {
        int chk = 0, off = 0, bent = 0, held = 0;
        double maxMoving = 0, maxHeld = 0;
        int frames = Math.Min(2 * loop, latch.Length / MidiModel.LatchBytes - start);
        double Sem(int k) => ideal.Semis[Math.Clamp(k, 0, loop - 1)];
        for (int f = 0; f < frames; f++)
        {
            int k = f % loop;
            int n = ideal.Note[k];
            if (n < 0 || Enumerable.Range(-2, 5).Any(d => ideal.NoteFrames.Contains(k + d))) continue;
            var l = latch.AsSpan((start + f) * MidiModel.LatchBytes, MidiModel.LatchBytes);
            bool sounding = channel == 2 ? MidiModel.Field(l, 5) != 0 : MidiModel.Field(l, channel * 2 + 1) > 0;
            if (!sounding) continue;
            double x = n + Sem(k);
            double exact = Vrun.Audio.Bends.ExactPeriod(x);
            if (exact > 0x7FF) continue;
            int reg = MidiModel.Field(l, channel == 2 ? 4 : channel * 2);
            chk++;
            bool isHeld = Enumerable.Range(-3, 7).All(d => Sem(k + d) == Sem(k));
            int rule = Math.Max(0, (int)Math.Floor(exact));
            double err = Math.Abs(Vrun.Audio.Bends.CentsOff(reg, x) - Vrun.Audio.Bends.CentsOff(rule, x));
            bool ok;
            if (isHeld) ok = reg == rule;
            else if (slidesOff) ok = true;
            else
            {
                double speed = 100.0 * Math.Min(Math.Abs(Sem(k) - Sem(k - 2)), Math.Abs(Sem(k + 2) - Sem(k))) / 2.0;
                double t2 = Math.Max(tol, speed / 2.0);
                ok = reg == rule || reg == (int)Math.Ceiling(exact) || Math.Abs(Vrun.Audio.Bends.CentsOff(reg, x)) <= t2 + 1e-9;
            }
            if (!ok) off++;
            if (Sem(k) != 0)
            {
                bent++;
                if (isHeld) { held++; maxHeld = Math.Max(maxHeld, err); } else maxMoving = Math.Max(maxMoving, err);
            }
        }
        return new BendJudgement(chk, off, bent, held, maxMoving, maxHeld);
    }

    /// <summary>The songs whose bends VRUN's converter plays (bends on: the ones written here and the roster's songs whose mapped channels bend), with its reports. Chosen by the
    /// converter itself, not by the plugin's path the check is about (so a plugin that drops the bends is judged on these songs, and fails).</summary>
    private static List<(MidiSong Song, SongResult Reference)> BendPlayers() =>
        Songs().Select(s => (s, R: SafeConvert(s.Midi))).Where(x => x.R != null && x.R.Bends.Any(b => !b.Ignored && !b.Dropped)).Select(x => (x.s, x.R!)).ToList();

    private static SongResult? SafeConvert(byte[] midi)
    {
        try { return Midi2Nes.ConvertSong(MidiFile.Parse(midi), SongConvert.TrackName, _ => { }, new ConvertOptions { Bends = true }); }
        catch (Exception e) when (e is FormatException or IndexOutOfRangeException or ArgumentOutOfRangeException) { return null; }
    }

    public static void BendsCheck(ImodelReport r)
    {
        var t = BundledTemplate();
        var (_, _, mlb) = MidiFixtures.Bundled();
        // 1. a song without bends converts exactly as before (round 7's converter, bends off): the plugin's switch to bends on changes nothing for it
        int same = 0, withBends = 0;
        foreach (var s in Songs())
        {
            var b = SongConvert.Convert(s.Midi, out _);
            if (b == null) continue;
            if (SafeConvert(s.Midi) is { } rr && rr.Bends.Any(x => !x.Ignored && !x.Dropped)) { withBends++; continue; }
            var old = Midi2Nes.ConvertSong(MidiFile.Parse(s.Midi), SongConvert.TrackName, _ => { });
            bool eq = Enumerable.Range(0, 4).All(c => b.Channels[c].AsSpan().SequenceEqual(old.Channels[c]));
            r.Expect(eq, $"{s.Name}: no channel of it plays a bend, yet the plugin's streams differ from the converter's without bends");
            if (eq) same++;
        }
        r.Note($"{same} songs without a played bend convert byte for byte as without bends; {withBends} play bends");
        if (MidiFixtures.Vrun() == null) NotRun(r, "the bends check on VRUN's roster songs that bend (the songs written here were checked)");

        // 2. the songs with bends, on the plugin's machine: the ROM's pitch against the MIDI's, the notes where they were without bends
        int songs = 0;
        var written = MidiFixtures.BendSongs().Select(x => x.Name).ToHashSet();
        foreach (var (s, reference) in BendPlayers())
        {
            var b = SongConvert.Convert(s.Midi, out _)!;
            var plain = Midi2Nes.ConvertSong(MidiFile.Parse(s.Midi), SongConvert.TrackName, _ => { });
            int loop = b.Facts.LoopFrames, n = Math.Min(2 * loop, 2400);
            var run = MidiRun.Of(t.Patch(b.Channels, loop, s.Name), n + MusicTemplate.Preroll + 4, mlb);
            var runPlain = MidiRun.Of(t.Patch(plain.Channels, loop, s.Name), n + MusicTemplate.Preroll + 4, mlb);
            int start = MidiModel.Best(b.Channels, run.Latch, n, skip: Skip).Start;
            int moved = 0;
            for (int f = 0; f < n; f++)
            {
                var a = run.Latch.AsSpan((start + f) * MidiModel.LatchBytes, MidiModel.LatchBytes);
                var c = runPlain.Latch.AsSpan((start + f) * MidiModel.LatchBytes, MidiModel.LatchBytes);
                foreach (int field in new[] { 1, 3, 5, 6, 7 }) if (MidiModel.Field(a, field) != MidiModel.Field(c, field)) { moved++; break; }
            }
            r.Expect(moved == 0, $"{s.Name}: with bends, the volume / triangle / noise registers differ from the song without bends in {moved} of {n} frames: the notes moved");
            var parts = new List<string>();
            foreach (var rep in reference.Bends.Where(x => !x.Ignored && !x.Dropped))
            {
                string ch = $"{s.Name} {MusicTemplate.ChannelNames[rep.NesChannel]}";
                var ideal = IdealPitch(s.Midi, rep.MidiChannel, loop);
                var j = JudgeBends(run.Latch, start, rep.NesChannel, ideal, loop, rep.ToleranceCents, rep.SlidesOff);
                var jp = JudgeBends(runPlain.Latch, start, rep.NesChannel, ideal, loop, rep.ToleranceCents, rep.SlidesOff);
                r.Expect(j.Off <= 2 * rep.FramesOverTolerance, $"{ch}: {j.Off} of {j.Checked} frames off the MIDI's pitch in the ROM (the converter says {rep.FramesOverTolerance} a loop)");
                if (written.Contains(s.Name)) r.Expect(j.Checked >= 20 && j.Bent >= 10, $"{ch}: only {j.Checked} frames ({j.Bent} bent) could be judged");
                if (j.Bent >= 10 && !rep.SlidesOff) r.Expect(jp.Off > j.Off, $"{ch}: without bends the ROM is no further off the MIDI's pitch ({jp.Off} frames) than with them ({j.Off}): this song cannot tell");
                parts.Add(j.Bent == 0
                    ? $"{MusicTemplate.ChannelNames[rep.NesChannel]}: no bent frame away from a note's start or end (notes too short to judge; the engine check holds its registers to the model)"
                    : $"{MusicTemplate.ChannelNames[rep.NesChannel]} {j.Bent} bent frames ({j.Held} held, max {j.MaxHeldCents:0.0} cents from the NES period; moving max {j.MaxMovingCents:0.0}), {j.Off} off (converter: {rep.FramesOverTolerance}/loop), {jp.Off} off without bends");
            }
            r.Note($"{s.Name,-12} " + string.Join("; ", parts) + (run.LateFrames > 0 ? $"; {run.LateFrames} frames whose NMI wrote on past the frame's end" : ""));
            songs++;
        }
        r.Expect(songs >= MidiFixtures.BendSongs().Count, $"only {songs} songs with bends were checked");
    }

    // ---- facts and refusals ----

    public static void Facts(ImodelReport r)
    {
        var all = MidiFixtures.Stress().ToDictionary(s => s.Name);
        SongFacts F(string name) { var b = SongConvert.Convert(all[name].Midi, out var why); r.Expect(b != null, $"{name} was refused: {why}"); return b?.Facts ?? new SongFacts(); }
        string L(SongFacts f) => string.Join(" | ", f.Lines());

        var syn = F("synthetic");
        // BrokenDev's measured figures for this song: square 1, triangle and noise, loop 480 frames, 121 bytes (the build report's total: the unmapped square 2 counts 1 byte there; patched, it is a 5-byte silent loop)
        r.Expect(syn.NotesDropped == 0 && syn.NotesTotal == 40 && syn.LoopFrames == 480 && syn.Bytes.Sum() == 121 && syn.Source[0] == 1 && syn.Source[1] == 0 && syn.Source[2] == 2 && syn.Source[3] == 10,
            $"the synthetic song's facts are not BrokenDev's measured ones (40 notes, square 1 <- 1, triangle <- 2, noise <- 10, loop 480, 121 bytes): {L(syn)}");
        r.Expect(L(syn).Contains("square 2 silent") && L(syn).Contains("all 40 notes have a NES channel") && L(syn).Contains("loop 480 frames (7.99 s)") && L(syn).Contains("fits:"), "the synthetic song's lines do not say it: " + L(syn));
        var dense = F("dense");
        r.Expect(dense.ThinnedTotal > 0 && L(dense).Contains("thinned"), "the dense song's thinning is not said: " + L(dense));
        var lng = F("long");
        r.Expect(lng.AnyTruncated && L(lng).Contains("truncated (over 1,280 bytes): square 1 1,923, triangle 3,843; they go silent before the loop"), "the long song's truncation is not said: " + L(lng));
        var many = F("manychannels");
        r.Expect(many.NotesDropped > 0 && many.DroppedChannels.Count >= 4 && L(many).Contains($"{many.NotesDropped} of {many.NotesTotal} notes dropped"), "the dropped channels are not said: " + L(many));
        r.Expect(many.TempoChangesIgnored == 2 && L(many).Contains("2 later tempo changes ignored"), "the ignored tempo changes are not counted right: " + L(many));
        // round 9: its 16 bends (MIDI 2, the default range) play on square 1 now
        r.Expect(many.PitchBends == 16 && many.BendMask == 1 && L(many).Contains("bends played on square 1:") && !L(many).Contains("not played"), "the pitch bends are not said played on square 1: " + L(many));
        // the bend songs
        var bends = MidiFixtures.BendSongs().ToDictionary(s => s.Name);
        SongFacts B(string name) { var b = SongConvert.Convert(bends[name].Midi, out var why); r.Expect(b != null, $"{name} was refused: {why}"); return b?.Facts ?? new SongFacts(); }
        var all3 = B("bendall");
        r.Expect(all3.BendMask == 7 && L(all3).Contains("bends played on square 1, square 2, triangle:") && L(all3).Contains("not played on noise (no pitch)"), "the bends of bendall (three channels played, the drums' not) are not said: " + L(all3));
        var glides = B("bendglides");
        r.Expect(glides.BendMask == 1 && glides.BendOpcodes > 0 && glides.BendBytes > 0 && L(glides).Contains($"(+{glides.BendBytes} bytes)") && L(glides).Contains("moving within"), "the glides' bend line does not give its numbers: " + L(glides));
        var pre = B("bendprebent");
        r.Expect(pre.BendMask == 3 && L(pre).Contains("held exact") && pre.BendsPlayed.Sum(x => x.NoteOnsAsPitch) > 0, "the bent notes (pitch steps, held exact) are not said: " + L(pre));
        var thin = B("benddense");
        r.Expect(thin.BendFramesOff > 0 && L(thin).Contains($"{thin.BendFramesOff} bend frame{(thin.BendFramesOff == 1 ? "" : "s")} thinned"), "the thinned bend frames of benddense are not said: " + L(thin));
        foreach (var s in MidiFixtures.Stress().Concat(MidiFixtures.BendSongs()))
            if (SongConvert.Convert(s.Midi, out _) is { } bb) r.Expect(bb.Facts.Lines().Count <= 6, $"{s.Name}: {bb.Facts.Lines().Count} fact lines, the window shows six");
        r.Note($"bendall: {L(all3)}");
        r.Note($"benddense: {L(thin)}");
        // drums only: the converter's own rule leaves them out (its fixed map is MIDI 1-4 when no other channel exists): refused, with that reason
        r.Expect(SongConvert.Convert(all["drumsonly"].Midi, out var dw) == null && dw != null && dw.Contains("only drums"), "the drums-only song (the converter plays nothing of it) was not refused with the reason: " + dw);
        var low = F("lownotes");
        r.Expect(low.LowNotes == 5 && L(low).Contains("5 notes below A1"), "the notes below A1 are not counted: " + L(low));
        foreach (var s in MidiFixtures.Refused())
        {
            var b = SongConvert.Convert(s.Midi, out var why);
            string expect = s.Name switch { "nonotes" => "no notes", "notmidi" or "empty" => "not a MIDI file", _ => "it ends in the middle" };
            r.Expect(b == null && why != null && why.Contains(expect), $"{s.Name} ({s.Source}): {(b != null ? "accepted" : $"refused with '{why}', expected it to say '{expect}'")}");
        }
        var huge = new byte[SongConvert.MaxMidiBytes + 1];
        r.Expect(SongConvert.Convert(huge, out var hw) == null && hw!.Contains("far smaller"), "a file over the size limit was accepted");
        r.Note($"synthetic: {L(syn)}");
        r.Note($"manychannels: {L(many)}");
    }

    public static void Section(ImodelReport r)
    {
        var midi = MidiFixtures.Synthetic();
        var s = new SongSection(@"C:\Music\my song.mid", midi, true, true, false);
        var bytes = s.Build();
        var back = SongSection.Read(bytes, out var p);
        r.Expect(back != null && back.Path == s.Path && back.Midi.AsSpan().SequenceEqual(midi) && back.Active && back.FollowTransport && !back.Stopped, "the section does not round-trip: " + p);
        foreach (var (a, f, st) in new[] { (false, false, true), (true, false, true), (false, true, false) })
        {
            var b2 = SongSection.Read(new SongSection("x.mid", midi, a, f, st).Build(), out _);
            r.Expect(b2 != null && b2.Active == a && b2.FollowTransport == f && b2.Stopped == st, $"the flags {a}/{f}/{st} do not round-trip");
        }
        int refused = 0;
        for (int n = 0; n < bytes.Length; n++) { if (SongSection.Read(bytes.AsSpan(0, n), out var why) == null && why != null) refused++; else r.Expect(false, $"a section cut to {n} of {bytes.Length} bytes was accepted"); }
        for (int i = 0; i < bytes.Length; i++)
        {
            var hit = (byte[])bytes.Clone(); hit[i] ^= (byte)(1 << (i % 8));
            if (SongSection.Read(hit, out var why) == null && why != null) refused++; else r.Expect(false, $"a section with byte {i} flipped was accepted");
        }
        // a newer version and an unknown flag (with a valid checksum: the checks must not lean on the CRC), lengths that lie
        byte[] Resum(byte[] b) { var c = (byte[])b.Clone(); System.Buffers.Binary.BinaryPrimitives.WriteUInt32LittleEndian(c.AsSpan(c.Length - 4), BrokenNes2.Music.Crc32.Of(c.AsSpan(0, c.Length - 4))); return c; }
        var newer = (byte[])bytes.Clone(); newer[0] = 2;
        r.Expect(SongSection.Read(Resum(newer), out var nw) == null && nw!.Contains("newer"), "a newer section was accepted: " + nw);
        var flag = (byte[])bytes.Clone(); flag[2] |= 0x40;
        r.Expect(SongSection.Read(Resum(flag), out var fw) == null && fw!.Contains("does not know"), "an unknown flag was accepted: " + fw);
        var lie = (byte[])bytes.Clone(); lie[8] ^= 4;
        r.Expect(SongSection.Read(Resum(lie), out var lw) == null && lw!.Contains("lengths"), "a lying MIDI length was accepted: " + lw);
        var nomidi = new SongSection("x.mid", [], true, true, false).Build();
        r.Expect(SongSection.Read(nomidi, out var ew) == null && ew!.Contains("no MIDI"), "a section without the MIDI file was accepted");
        r.Note($"{refused} cut or damaged sections refused (every length, a flipped bit in every byte), newer / unknown-flag / lying / empty refused");
    }

    // =====================================================================================================================================================================
    // runner and deliberate bugs
    // =====================================================================================================================================================================

    public sealed record Mutant(string Name, string CatchingCheck, Action Arm, Action Disarm);

    public static readonly Mutant[] Mutants =
    [
        new("every note one semitone up after conversion", "converter", () => MusicMutate.Mask = MusicMutate.ConverterOffByOne, () => MusicMutate.Mask = 0),
        new("square 1 patched one byte late", "engine", () => MusicMutate.Mask = MusicMutate.PatchSkew, () => MusicMutate.Mask = 0),
        new("square 1 patched one byte late", "title", () => MusicMutate.Mask = MusicMutate.PatchSkew, () => MusicMutate.Mask = 0),
        new("square 1 patched one byte late", "reference", () => MusicMutate.Mask = MusicMutate.PatchSkew, () => MusicMutate.Mask = 0),
        new("the fresh template's engine changed in one byte", "template", () => FreshEngineByteFlipped = true, () => FreshEngineByteFlipped = false),
        new("the facts say no note was dropped", "facts", () => MusicMutate.Mask = MusicMutate.FactsHideDropped, () => MusicMutate.Mask = 0),
        new("the section is written without the MIDI file", "section", () => MusicMutate.Mask = MusicMutate.SectionDropsMidi, () => MusicMutate.Mask = 0),
        // round 9 (pitch bends)
        new("the song is converted with bends off (round 7's way)", "bends", () => MusicMutate.Mask = MusicMutate.BendsIgnored, () => MusicMutate.Mask = 0),
        new("every slide's slope negated after conversion", "bends", () => MusicMutate.Mask = MusicMutate.SlideSignFlipped, () => MusicMutate.Mask = 0),
        new("the facts say no bend frame was thinned", "facts", () => MusicMutate.Mask = MusicMutate.FactsHideBendLoss, () => MusicMutate.Mask = 0),
        new("a version-1 template (plain decoders) is accepted", "template-refusals", () => MusicMutate.Mask = MusicMutate.OldTemplateAccepted, () => MusicMutate.Mask = 0),
    ];

    public static List<CheckOutcome> RunChecks(string? only, Action<string>? log = null)
    {
        var list = new List<CheckOutcome>();
        foreach (var c in All)
        {
            if (only != null && !only.Split(',').Contains(c.Id)) continue;
            var r = new ImodelReport();
            var sw = Stopwatch.StartNew();
            try { c.Run(r); }
            catch (Exception e) { r.Failures.Add($"exception {e.GetType().Name}: {e.Message} @ {e.StackTrace?.Split('\n').FirstOrDefault()?.Trim()}"); }
            var o = new CheckOutcome(c.Id, c.What, r.Failures.Count == 0, sw.Elapsed.TotalSeconds, r);
            list.Add(o);
            string verdict = !o.Passed ? "FAIL" : NotRunAtAll(o) ? "NOT RUN" : r.Warnings.Count > 0 ? "WARN" : "PASS";
            log?.Invoke($"  {verdict,-7} {c.Id,-18} {r.Assertions,7} assertions  [{o.Seconds:0.0}s]" + (r.Notes.Count > 0 ? "\n        " + string.Join("\n        ", r.Notes) : "") + (r.Warnings.Count > 0 ? "\n        warning: " + string.Join("\n        warning: ", r.Warnings) : "") + (r.Failures.Count > 0 ? "\n        FAILED: " + string.Join("\n        FAILED: ", r.Failures.Take(8)) + (r.Failures.Count > 8 ? $"\n        ... and {r.Failures.Count - 8} more" : "") : ""));
        }
        return list;
    }

    /// <summary>A check that could not run at all (the VRUN tree is missing): never counted as passed.</summary>
    private static bool NotRunAtAll(CheckOutcome o) => o.Report.Assertions == 0 && o.Report.Warnings.Any(w => w.StartsWith("NOT RUN"));

    public static (List<string> Lines, int Missed) RunMutants(string? only)
    {
        var lines = new List<string>();
        int missed = 0;
        foreach (var m in Mutants)
        {
            if (only != null && !only.Split(',').Contains(m.CatchingCheck)) continue;
            var check = All.First(c => c.Id == m.CatchingCheck);
            var r = new ImodelReport();
            m.Arm();
            try { check.Run(r); }
            catch (Exception e) { r.Failures.Add($"exception {e.GetType().Name}: {e.Message}"); }
            finally { m.Disarm(); }
            bool notRun = r.Warnings.Any(w => w.StartsWith("NOT RUN")) && r.Failures.Count == 0;
            bool caught = r.Failures.Count > 0;
            if (!caught && !notRun) missed++;
            lines.Add($"  {(caught ? "caught" : notRun ? "NOT RUN" : "MISSED")}  [{m.CatchingCheck}] {m.Name}: {r.Failures.Count} failing assertions" + (caught ? $", e.g. {(r.Failures[0].Length > 170 ? r.Failures[0][..167] + "..." : r.Failures[0])}" : ""));
        }
        return (lines, missed);
    }

    /// <summary>`FruityHost midi-trace &lt;song name&gt; [from] [to]`: the APU fields of the patched template frame by frame (a development aid: what the engine check compares).</summary>
    public static int Trace(string[] args)
    {
        var s = Songs().FirstOrDefault(x => x.Name == args[1]);
        if (s == null) { Console.WriteLine("songs: " + string.Join(", ", Songs().Select(x => x.Name))); return 2; }
        int from = args.Length > 2 ? int.Parse(args[2]) : 0, to = args.Length > 3 ? int.Parse(args[3]) : 20;
        var t = BundledTemplate();
        var b = SongConvert.Convert(s.Midi, out var why) ?? throw new InvalidOperationException(why);
        var run = MidiRun.Of(t.Patch(b.Channels, b.Facts.LoopFrames, s.Name), to + 1, MidiFixtures.Bundled().Mlb);
        Console.WriteLine("frame  " + string.Join(" ", MidiModel.FieldNames.Select(f => f.PadLeft(5))) + "   raw latch $4000-$400F");
        for (int f = from; f <= to; f++)
        {
            var l = run.Latch.AsSpan(f * MidiModel.LatchBytes, MidiModel.LatchBytes).ToArray();
            Console.WriteLine($"{f,5}  " + string.Join(" ", Enumerable.Range(0, 8).Select(k => MidiModel.Field(l, k).ToString("X").PadLeft(5))) + "   " + Convert.ToHexString(l.AsSpan(0, 16)));
        }
        Console.WriteLine("streams: " + string.Join(" | ", b.Channels.Select(c => Convert.ToHexString(c.AsSpan(0, Math.Min(12, c.Length))))));
        return 0;
    }

    /// <summary>`FruityHost midi-test [--only id,id] [--no-mutants]`</summary>
    public static int Main(string[] args)
    {
        string? only = null;
        for (int i = 0; i < args.Length - 1; i++) if (args[i] == "--only") only = args[i + 1];
        bool mutants = !args.Contains("--no-mutants");
        Console.WriteLine($"BrokenNes.FruityHost midi-test (Test MIDI export: the converter, the template, the engine, the facts, the project section; no plugin DLL involved). VRUN tree: {MidiFixtures.Vrun() ?? "NOT on this machine"}");
        var results = RunChecks(only, Console.WriteLine);
        int failed = results.Count(o => !o.Passed), missed = 0;
        if (mutants)
        {
            Console.WriteLine("deliberate bugs (each must be caught by the check named):");
            var (lines, m) = RunMutants(only);
            foreach (var l in lines) Console.WriteLine(l);
            missed = m;
        }
        int notRun = results.Count(NotRunAtAll), partly = results.Count(o => !NotRunAtAll(o) && o.Report.Warnings.Any(w => w.StartsWith("NOT RUN")));
        Console.WriteLine($"{results.Count - failed - notRun} checks passed ({partly} of them with parts NOT RUN), {notRun} NOT RUN (the VRUN tree is not on this machine: not passed), {failed} failed, {results.Sum(o => o.Report.Assertions)} assertions; {missed} deliberate bugs missed");
        return failed == 0 && missed == 0 ? 0 : 1;
    }
